program.compute:
rows = read('/input/options')
result = None
for count in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(rows, count):
        proposal = [row['id'] for row in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
exists('/output/selection')
if exists('/output/selection'):
    result = read('/output/selection')
    if not valid(result):
        status('report')
else:
    write('/output/selection', result)
state = status('report')
if state == 'not_sent':
    send('report', 'team', result)
    state = status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

